///  Sensor Bias Contribution - exactly one arm is set.
public struct SBC: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$SBC" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: SBC.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let REQUEST: VOffset = 4
    static let DIAGNOSTICS: VOffset = 6
  }

  public var REQUEST: SBCCovarianceRequest? { let o = _accessor.offset(VT.REQUEST); return o == 0 ? nil : SBCCovarianceRequest(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public var DIAGNOSTICS: SBCDiagnostics? { let o = _accessor.offset(VT.DIAGNOSTICS); return o == 0 ? nil : SBCDiagnostics(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startSBC(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 2) }
  public static func add(REQUEST: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REQUEST, at: VT.REQUEST) }
  public static func add(DIAGNOSTICS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DIAGNOSTICS, at: VT.DIAGNOSTICS) }
  public static func endSBC(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createSBC(
    _ fbb: inout FlatBufferBuilder,
    REQUESTOffset REQUEST: Offset = Offset(),
    DIAGNOSTICSOffset DIAGNOSTICS: Offset = Offset()
  ) -> Offset {
    let __start = SBC.startSBC(&fbb)
    SBC.add(REQUEST: REQUEST, &fbb)
    SBC.add(DIAGNOSTICS: DIAGNOSTICS, &fbb)
    return SBC.endSBC(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.REQUEST, fieldName: "REQUEST", required: false, type: ForwardOffset<SBCCovarianceRequest>.self)
    try _v.visit(field: VT.DIAGNOSTICS, fieldName: "DIAGNOSTICS", required: false, type: ForwardOffset<SBCDiagnostics>.self)
    _v.finish()
  }
